}

fn main() {
    println!("{}", parse_and_double("42"));
}

exercise.solution:
fn parse_and_double(text: &str) -> i32 {
    let n: i32 = text.parse().expect("not a number");
    n * 2
}

fn main() {
    println!("{}", parse_and_double("42"));
}
